1\\u043b\\u0438\\u043a\\u0430\\u0446\\u0438\\u0439 (Yang et al., 2023 \\u2014 \\u00abLarge Language Models as Optimizers\\u00bb; Suzgun et al., 2022 \\u2014 BBH) \\u0438 \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u043e\\u0432, \\u043f\\u0440\\u0438\\u0432\\u043b\\u0435\\u043a\\u0430\\u0435\\u043c\\u044b\\u0445 \\u00ab\\u043f\\u043e \\u043e\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u044e\\u00bb, \\u0430 \\u043d\\u0435 \\u0438\\u0437 \\u043b\\u043e\\u043a\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u0444\\u0430\\u0439\\u043b\\u043e\\u0432. \\u042d\\u0442\\u043e \\u2014 \\u043a\\u0440\\u0438\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435, \\u044f\\u0432\\u043d\\u043e \\u0432\\u044b\\u0434\\u0435\\u043b\\u044f\\u044e \\u043d\\u0438\\u0436\\u0435.\\n\\n---\\n\\n## \\u042d\\u0442\\u0430\\u043f B \\u2014 \\u041f\\u0440\\u0435\\u0434\\u043b\\u043e\\u0436\\u0435\\u043d\\u043d\\u044b\\u0439 \\u043a\\u0430\\u0440\\u043a\\u0430\\u0441 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430 (\\u0431\\u0435\\u0437 \\u0434\\u0435\\u0442\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0440\\u0430\\u0437\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0438)\\n\\n\\u041e\\u0442\\u0432\\u0435\\u0442 \\u043d\\u0430 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f **\\u00ab\\u043f\\u0440\\u0435\\u0432\\u043e\\u0441\\u0445\\u043e\\u0434\\u044f\\u0442 \\u043b\\u0438 OPRO-\\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438 \\u0431\\u0430\\u0437\\u043e\\u0432\\u044b\\u0435 \\u043d\\u0430 BBH?\\u00bb** \\u043f\\u0440\\u0435\\u0434\\u043b\\u0430\\u0433\\u0430\\u0435\\u0442\\u0441\\u044f \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u0438\\u0442\\u044c \\u0432 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0435 **paired, per-task, with-instruction-swap** (\\u0442\\u043e \\u0435\\u0441\\u0442\\u044c \\u043e\\u0434\\u043d\\u0430 \\u0438 \\u0442\\u0430 \\u0436\\u0435 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c/\\u0434\\u0435\\u043a\\u043e\\u0434\\u0438\\u043d\\u0433 \\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u043e\\u043c \\u0438\\u0437 27 BBH-\\u0437\\u0430\\u0434\\u0430\\u0447 \\u0438 \\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u043e\\u043c \\u0438\\u0437 \\u043e\\u0431\\u0440\\u0430\\u0431\\u0430\\u0442\\u044b\\u0432\\u0430\\u0435\\u043c\\u044b\\u0445 \\u0443\\u0440\\u043e\\u0432\\u043d\\u0435\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438, \\u0447\\u0442\\u043e\\u0431\\u044b \\u0440\\u0430\\u0437\\u043b\\u0438\\u0447\\u0438\\u0435 \\u043e\\u0431\\u044a\\u044f\\u0441\\u043d\\u044f\\u043b\\u043e\\u0441\\u044c \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0442\\u0435\\u043a\\u0441\\u0442\\u043e\\u043c \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438).\\n\\n### B.1. \\u041f\\u0435\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u044b\\u0435\\n- **\\u0424\\u0430\\u043a\\u0442\\u043e\\u0440 X (\\u0442\\u0438\\u043f \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438), \\u0443\\u0440\\u043e\\u0432\\u043d\\u0438 (\\u043f\\u043b\\u0430\\u043d\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f 3 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u044b\\u0445 + 1 \\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439):**\\n  1. **OPRO-best** \\u2014 \\u043b\\u0443\\u0447\\u0448\\u0430\\u044f \\u043f\\u043e \\u0441\\u043a\\u043e\\u0440\\u0443 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f, \\u043e\\u0431\\u043d\\u0430\\u0440\\u0443\\u0436\\u0435\\u043d\\u043d\\u0430\\u044f OPRO \\u0434\\u043b\\u044f \\u0434\\u0430\\u043d\\u043d\\u043e\\u0439 BBH-\\u043f\\u043e\\u0434\\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0438 (\\u0438\\u043b\\u0438 \\u0435\\u0434\\u0438\\u043d\\u0430\\u044f best \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f OPRO \\u0438\\u0437 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438, \\u0435\\u0441\\u043b\\u0438 \\u0432 \\u043f\\u0443\\u0431\\u043b\\u0438\\u0447\\u043d\\u044b\\u0445 \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u0430\\u0445 \\u043d\\u0435\\u0442 per-task \\u2014 \\u0432\\u044b\\u0431\\u043e\\u0440 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u043c \\u043a\\u0430\\u043a \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435 \\u043d\\u0438\\u0436\\u0435).\\n  2. **OPRO top-k (\\u0435\\u0441\\u043b\\u0438 \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u043e \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e):** `k\\u2208{3,5}` \\u0442\\u043e\\u043f\\u043e\\u0432\\u044b\\u0445 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0439 OPRO (\\u0434\\u043b\\u044f \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430 \\u0443\\u0441\\u0442\\u043e\\u0439\\u0447\\u0438\\u0432\\u043e\\u0441\\u0442\\u0438 \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0430) \\u2014 **\\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u0438\\u043c\\u043e \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043f\\u0440\\u0438 \\u043d\\u0430\\u043b\\u0438\\u0447\\u0438\\u0438 \\u0432 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0435**, \\u0438\\u043d\\u0430\\u0447\\u0435 \\u0443\\u0440\\u043e\\u0432\\u0435\\u043d\\u044c \\u043e\\u043f\\u0443\\u0441\\u043a\\u0430\\u0435\\u0442\\u0441\\u044f.\\n  3. **Baseline-1: \\\"Let's think step by step.\\\"** (\\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u044b\\u0439 CoT-trigger; Kojima et al., 2022).\\n  4. **Baseline-2: \\\"\\\" (empty prompt)** \\u2014 \\u0431\\u0435\\u0437 \\u043a\\u0430\\u043a\\u043e\\u0433\\u043e-\\u043b\\u0438\\u0431\\u043e \\u043f\\u0440\\u0435\\u0444\\u0438\\u043a\\u0441\\u0430-\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438; \\u043f\\u0435\\u0440\\u0432\\u0430\\u044f \\u0441\\u0442\\u0440\\u043e\\u043a\\u0430 \\u0432\\u0432\\u043e\\u0434\\u0430 \\u2014 \\u0442\\u0435\\u043a\\u0441\\u0442 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 BBH.\\n- **\\u0417\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u0430\\u044f \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u0430\\u044f Y:** `task_accuracy = (#\\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u044c\\u043d\\u043e \\u0440\\u0430\\u0441\\u043f\\u0430\\u0440\\u0441\\u0435\\u043d\\u043d\\u044b\\u0445 \\u043e\\u0442\\u0432\\u0435\\u0442\\u043e\\u0432) / N_task` \\u0432 \\u0440\\u0435\\u0436\\u0438\\u043c\\u0435 exact-match \\u043f\\u043e\\u0441\\u043b\\u0435 \\u043d\\u043e\\u0440\\u043c\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438; **\\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442**: `BBH_macro_accuracy = mean_i task_acc_i` \\u0438 `BBH_micro_accuracy = sum correct / sum N` (\\u043e\\u0431\\u0430 \\u0440\\u0430\\u043f\\u043e\\u0440\\u0442\\u0443\\u044e\\u0442\\u0441\\u044f). \\u0414\\u043e\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e: \\u0434\\u043b\\u0438\\u043d\\u0430 rationale \\u0432 \\u0442\\u043e\\u043a\\u0435\\u043d\\u0430\\u0445 (\\u043a\\u0430\\u043a \\u043a\\u043e\\u0432\\u0430\\u0440\\u0438\\u0430\\u0442\\u0430).\\n- **\\u041a\\u043e\\u0432\\u0430\\u0440\\u0438\\u0430\\u0442\\u044b \\u043d\\u0430 \\u0443\\u0440\\u043e\\u0432\\u043d\\u0435 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438:** \\u0442\\u0438\\u043f \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 BBH (multiple-choice vs free-form), \\u043d\\u0430\\u043b\\u0438\\u0447\\u0438\\u0435 few-shot-\\u0434\\u0435\\u043c\\u043e\\u043d\\u0441\\u0442\\u0440\\u0430\\u0446\\u0438\\u0439 \\u0432 \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u043e\\u043c \\u043f\\u0440\\u043e\\u043c\\u043f\\u0442\\u0435 BBH (true \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445 27, \\u043d\\u043e \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u043c), \\u0434\\u043b\\u0438\\u043d\\u0430 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438 \\u0432 \\u0441\\u0438\\u043c\\u0432\\u043e\\u043b\\u0430\\u0445.\\n\\n### B.2. BBH-\\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0430\\n- **\\u041f\\u043e\\u043b\\u043d\\u044b\\u0439 \\u043d\\u0430\\u0431\\u043e\\u0440 27 \\u0437\\u0430\\u0434\\u0430\\u0447 BBH** (Suzgun et al., 2022: causal_judgement, date_understanding, disambiguation_qa, formal_fallacies, geometric_shapes, hyperbaton, logical_deduction (3), movie_recommendation, multistep_arithmetic, navigate, object_counting, penguins_in_a_table, reasoning_colored_objects, ruin_names, salient_translation_error, snarks, sports_understanding, temporal_sequences, tracking_shuffled_objects (3), web_of_lies, word_sorting).\\n- **\\u041e\\u0431\\u043e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\\"\\u043f\\u043e\\u043b\\u043d\\u044b\\u0439, \\u0430 \\u043d\\u0435 \\u043f\\u043e\\u0434\\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u043e\\\":** (i) \\u0444\\u0430\\u043a\\u0442\\u043e\\u0440\\u043e\\u043c \\u044f\\u0432\\u043b\\u044f\\u044e\\u0442\\u0441\\u044f \\u0441\\u0430\\u043c\\u0438 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438, \\u043f\\u043e\\u044d\\u0442\\u043e\\u043c\\u0443 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442\\u0441\\u044f \\u0448\\u0438\\u0440\\u043e\\u043a\\u0438\\u0439 \\u043e\\u0445\\u0432\\u0430\\u0442; (ii) \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442 \\u0438 \\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u044f \\u00abOPRO vs \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 baseline\\u00bb \\u0435\\u0441\\u0442\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b \\u043d\\u0430 27 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u0445; (iii) \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u043d\\u0430 27 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u0445 \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0430 BBH-\\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430 \\u0432 \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u0445 OPRO/BBH \\u2014 \\u0441\\u043e\\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c \\u0441 \\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u043c\\u0438 \\u0447\\u0438\\u0441\\u043b\\u0430\\u043c\\u0438; (iv) \\u043f\\u043e\\u0434\\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u043e \\u043f\\u0440\\u0438\\u0432\\u0435\\u0434\\u0451\\u0442 \\u043a \\u043f\\u043e\\u0442\\u0435\\u0440\\u0435 \\u043c\\u043e\\u0449\\u043d\\u043e\\u0441\\u0442\\u0438 \\u043f\\u0430\\u0440\\u043d\\u043e\\u0433\\u043e \\u0442\\u0435\\u0441\\u0442\\u0430 \\u0438 \\u0441\\u043c\\u0435\\u0449\\u0435\\u043d\\u0438\\u044e \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442\\u0430.\\n- **\\u0420\\u0430\\u0437\\u043c\\u0435\\u0440 \\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0438 \\u043d\\u0430 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0443:** \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u0442\\u044c **\\u043f\\u043e\\u043b\\u043d\\u044b\\u0439 eval-\\u0441\\u043f\\u043b\\u0438\\u0442 BBH (\\u043e\\u0431\\u044b\\u0447\\u043d\\u043e 250 \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432 \\u043d\\u0430 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0443, sum \\u2248 6 511), one-shot seed determinism**; \\u043d\\u0435 \\u0441\\u0443\\u0431\\u0441\\u044d\\u043c\\u043f\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c, \\u0447\\u0442\\u043e\\u0431\\u044b \\u043a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0442\\u043d\\u043e \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u0442\\u044c \\u0441 \\u043f\\u0430\\u0440\\u043d\\u044b\\u043c\\u0438 \\u0442\\u0435\\u0441\\u0442\\u0430\\u043c\\u0438 \\u043d\\u0430 \\u0443\\u0440\\u043e\\u0432\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u0430.\\n- **\\u041e\\u0431\\u043e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432 \\u043f\\u043e\\u0434\\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0430:** \\u0432 \\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438 OPRO \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u044f \\u0434\\u0435\\u043b\\u0430\\u044e\\u0442\\u0441\\u044f \\u043d\\u0430 \\u043f\\u043e\\u043b\\u043d\\u043e\\u043c eval-\\u0441\\u043f\\u043b\\u0438\\u0442\\u0435 (\\u0438\\u043b\\u0438 \\u0441\\u043e\\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u0438\\u043c\\u043e\\u043c); \\u0441\\u0443\\u0431-\\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0430 \\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0432\\u0435\\u043b\\u0438\\u0447\\u0435\\u043d\\u0438\\u044f \\u043f\\u043e\\u0432\\u0442\\u043e\\u0440\\u043d\\u044b\\u0445 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u043e\\u0432 \\u0434\\u043b\\u044f \\u043c\\u043e\\u0449\\u043d\\u043e\\u0441\\u0442\\u0438, \\u0447\\u0442\\u043e \\u0432 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f\\u0445 `actor_step_budget=60` \\u0438 offline/\\u0431\\u0435\\u0437 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 \\u043d\\u0435\\u0440\\u0435\\u0430\\u043b\\u0438\\u0441\\u0442\\u0438\\u0447\\u043d\\u043e \\u0440\\u0435\\u0448\\u0430\\u0442\\u044c \\u043a\\u0430\\u043a \\u0440\\u0430\\u043d\\u0442\\u0430\\u0439\\u043c \\u2014 \\u0442\\u043e \\u0435\\u0441\\u0442\\u044c \\u043a\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438\\u0439 sub-sampling \\u0434\\u043e\\u043f\\u0443\\u0441\\u0442\\u0438\\u043c \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043f\\u0440\\u0438 \\u044f\\u0432\\u043d\\u043e \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0451\\u043d\\u043d\\u043e\\u0439 \\u0438\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u0438 OPRO-\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0439 \\u043d\\u0430 \\u044d\\u0442\\u043e\\u043c sub-sampling.\\n\\n### B.3. \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0438\\n- **\\u041c\\u043e\\u0434\\u0435\\u043b\\u044c \\u0438 \\u0434\\u0435\\u043a\\u043e\\u0434\\u0438\\u043d\\u0433:** \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c LLM (\\u043f\\u043e \\u0443\\u043c\\u043e\\u043b\\u0447\\u0430\\u043d\\u0438\\u044e \\u2014 \\u0442\\u0435\\u043a\\u0441\\u0442-LM, \\u043d\\u0430 \\u043a\\u043e\\u0442\\u043e\\u0440\\u043e\\u0439 \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u043b\\u0441\\u044f OPRO \\u0432 \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435, e.g., `text-bison` / `PaLM 2-L`); **\\u0440\\u043e\\u0432\\u043d\\u043e \\u043e\\u0434\\u0438\\u043d \\u0434\\u0435\\u043a\\u043e\\u0434\\u0438\\u043d\\u0433** \\u2014 `temperature=0.0`, `top_p=1.0`, `max_output_tokens` (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, 512), `stop_sequences` \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u044b. \\u0415\\u0441\\u043b\\u0438 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c \\u0432\\u044b\\u0431\\u0438\\u0440\\u0430\\u0435\\u0442 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c \\u2014 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u043c \\u044f\\u0432\\u043d\\u043e.\\n- **Few-shot \\u0440\\u0435\\u0436\\u0438\\u043c:** \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u044b\\u0439 **3-shot prefix** \\u0438\\u0437 BBH (\\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442 BBH-\\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0430), \\u043b\\u0438\\u0431\\u043e **0-shot** \\u2014 \\u0432\\u044b\\u0431\\u043e\\u0440 \\u043e\\u0434\\u043d\\u043e\\u0433\\u043e \\u0440\\u0435\\u0436\\u0438\\u043c\\u0430. \\u0414\\u0438\\u0437\\u0430\\u0439\\u043d \\u043d\\u0435 \\u0441\\u043c\\u0435\\u0448\\u0438\\u0432\\u0430\\u0435\\u0442 \\u0440\\u0435\\u0436\\u0438\\u043c\\u044b \\u043c\\u0435\\u0436\\u0434\\u0443 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0430\\u043c\\u0438 `(instruction \\u00d7 task)`. \\u042d\\u0442\\u043e **\\u043f\\u0435\\u0440\\u0432\\u044b\\u0439 \\u0443\\u0437\\u0435\\u043b \\u0434\\u043b\\u044f \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f** (\\u0441\\u043c. C).\\n- **\\u0421\\u0435\\u043c\\u043f\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435/seed:** \\u043f\\u0440\\u0438 temperature=0 \\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442 \\u0432\\u043e\\u0441\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u043c \\u043f\\u0440\\u0438 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u043c seed; \\u043f\\u0440\\u0438 \\u043d\\u0435\\u043d\\u0443\\u043b\\u0435\\u0432\\u043e\\u043c \\u2014 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u043c \\u043e\\u0434\\u0438\\u043d seed \\u043d\\u0430 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0443 \\u0438 \\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u0441\\u043e\\u043e\\u0431\\u0449\\u0430\\u0435\\u043c **mean \\u00b1 std \\u043f\\u043e n_seeds=3** \\u043a\\u043e\\u0440\\u043e\\u0442\\u043a\\u0438\\u0445 \\u0441\\u044d\\u043c\\u043f\\u043b\\u0438\\u043d\\u0433-\\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u043e\\u0432 \\u0434\\u043b\\u044f sanity-check \\u0432\\u0430\\u0440\\u0438\\u0430\\u0446\\u0438\\u0438.\\n- **Per-task N:** \\u0432\\u0441\\u0435 27 \\u0437\\u0430\\u0434\\u0430\\u0447 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u044f\\u044e\\u0442\\u0441\\u044f \\u0441 \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u043c N \\u0432 \\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0430\\u0445 runs.\\n- **OPRO-\\u0438\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c:** \\u043a\\u043e\\u043d\\u043a\\u0440\\u0435\\u0442\\u043d\\u044b\\u0435 \\u0442\\u0435\\u043a\\u0441\\u0442\\u044b \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0439, \\u043a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439 \\u043c\\u0438\\u043d\\u0438/\\u043c\\u0430\\u043a\\u0441 \\u0432 OPRO, \\u0447\\u0438\\u0441\\u043b\\u043e \\u0438\\u0442\\u0435\\u0440\\u0430\\u0446\\u0438\\u0439 OPRO \\u0438 seed \\u2014 **\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a \\u043f\\u0440\\u043e\\u0447\\u0438\\u0442\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0438\\u0437 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0430** \\u0438 \\u043f\\u043e\\u043c\\u0435\\u0449\\u0430\\u044e\\u0442\\u0441\\u044f \\u0432 \\\"OPRO provenance\\\" \\u0444\\u0430\\u0439\\u043b \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430.\\n- **\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c leakage:** BBH \\u043d\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043b\\u0430\\u0441\\u044c \\u043a\\u0430\\u043a training set \\u0434\\u043b\\u044f \\u0431\\u043e\\u043b\\u044c\\u0448\\u0438\\u043d\\u0441\\u0442\\u0432\\u0430 \\u0441\\u0440\\u0430\\u0432\\u043d\\u0438\\u0432\\u0430\\u0435\\u043c\\u044b\\u0445 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439 (\\u0434\\u043b\\u044f PaLM 2 / text-bison \\u2014 \\u044f\\u0432\\u043d\\u043e per \\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438). \\u0424\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u043c \\u044f\\u0432\\u043d\\u043e.\\n- **\\u041f\\u0430\\u0440\\u0441\\u0438\\u043d\\u0433 \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430:** \\u0435\\u0434\\u0438\\u043d\\u0430\\u044f \\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u0430 post-processing (regex-\\u0438\\u0437\\u0432\\u043b\\u0435\\u0447\\u0435\\u043d\\u0438\\u0435 \\u0444\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430 \\u0438\\u0437 `Final Answer:` \\u0438\\u043b\\u0438 \\u043f\\u0435\\u0440\\u0432\\u043e\\u0433\\u043e \\u0442\\u043e\\u043a\\u0435\\u043d\\u0430 multiple-choice) \\u2014 \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f **\\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u043e \\u043a\\u043e \\u0432\\u0441\\u0435\\u043c \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f\\u043c** (\\u0432\\u0430\\u0436\\u043d\\u043e \\u0434\\u043b\\u044f \\u0432\\u0430\\u043b\\u0438\\u0434\\u043d\\u043e\\u0441\\u0442\\u0438 paired-\\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u044f).\\n- **\\u0421\\u0440\\u0435\\u0434\\u043e\\u0432\\u044b\\u0435 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0438:** \\u0432 bubblewrap/\\u0431\\u0435\\u0437 \\u0441\\u0435\\u0442\\u0438/\\u0431\\u0435\\u0437 GPU \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 inference \\u043d\\u0435 \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430\\u0435\\u0442\\u0441\\u044f; \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u0434\\u043e\\u043b\\u0436\\u0435\\u043d \\u044d\\u0442\\u043e \\u0447\\u0435\\u0441\\u0442\\u043d\\u043e \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0438 \\u043e\\u043f\\u0438\\u0441\\u044b\\u0432\\u0430\\u0442\\u044c **\\u0441\\u0438\\u043c\\u0443\\u043b\\u044f\\u0446\\u0438\\u043e\\u043d\\u043d\\u044b\\u0439 \\u0441\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0439** \\u043d\\u0430 \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u0451\\u043d\\u043d\\u044b\\u0445 completion (\\u0435\\u0441\\u043b\\u0438 \\u043f\\u0440\\u0438\\u043b\\u043e\\u0436\\u0435\\u043d\\u044b) \\u043b\\u0438\\u0431\\u043e **paper-faithful reconstruction** \\u043d\\u0430 \\u043f\\u0443\\u0431\\u043b\\u0438\\u0447\\u043d\\u044b\\u0445 \\u0447\\u0438\\u0441\\u043b\\u0430\\u0445 \\u2014 \\u0432\\u044b\\u0431\\u043e\\u0440 \\u0437\\u0430 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u0435\\u043c (\\u0441\\u043c. C).\\n\\n### B.4. \\u0421\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043f\\u043b\\u0430\\u043d\\n- **Per-task paired test:** \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u043f\\u0430\\u0440\\u044b `(OPRO-best, baseline)` \\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0435 \\u2014 **\\u0434\\u0432\\u0443\\u0441\\u0442\\u043e\\u0440\\u043e\\u043d\\u043d\\u0438\\u0439** \\u043d\\u0435\\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0442\\u0435\\u0441\\u0442 \\u043d\\u0430 \\u0443\\u0440\\u043e\\u0432\\u043d\\u0435 \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432: **McNemar's test** (\\u043f\\u043e\\u0442\\u043e\\u043c\\u0443 \\u0447\\u0442\\u043e \\u043e\\u0442\\u0432\\u0435\\u0442\\u044b \\u0431\\u0438\\u043d\\u0430\\u0440\\u043d\\u044b\\u0435 \\u0438 \\u0441\\u044d\\u043c\\u043f\\u043b\\u044b \\u043f\\u0430\\u0440\\u043d\\u044b\\u0435) \\u0441 \\u043f\\u043e\\u043f\\u0440\\u0430\\u0432\\u043a\\u043e\\u0439 **Benjamini\\u2013Hochberg FDR (q=0.05)** \\u043f\\u043e 27\\u00d7\\u043a\\u043e\\u043b-\\u0432\\u043e \\u043f\\u0430\\u0440 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c.\\n- **Per-task effect size:** `Cohen's d` \\u043d\\u0430 per-task accuracy (\\u0438\\u043b\\u0438 `odds ratio` \\u043e\\u0442 McNemar) \\u2014 \\u0434\\u043b\\u044f \\u0438\\u043d\\u0442\\u0435\\u0440\\u043f\\u0440\\u0435\\u0442\\u0430\\u0446\\u0438\\u0438 \\u0432\\u0435\\u043b\\u0438\\u0447\\u0438\\u043d\\u044b \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0430.\\n- **\\u0410\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u044f:** (i) `macro_acc` \\u043f\\u043e 27 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c \\u0441 **95% Wilson-CI** \\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 \\u0443\\u0440\\u043e\\u0432\\u0435\\u043d\\u044c \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438; (ii) `micro_acc` \\u0441 Wilson-CI; (iii) **paired Wilcoxon signed-rank** \\u043f\\u043e 27 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u044f\\u043c `task_acc` \\u0443\\u0440\\u043e\\u0432\\u043d\\u044f OPRO vs baseline (\\u0430\\u0433\\u0440\\u0435\\u0433\\u0438\\u0440\\u0443\\u044e\\u0449\\u0438\\u0439 \\u0442\\u0435\\u0441\\u0442; \\u043d\\u0435\\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0438\\u0437-\\u0437\\u0430 \\u043d\\u0435\\u043d\\u043e\\u0440\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0438 per-task acc); \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442 \\u2014 `median difference` \\u0438 `rank-biserial r`.\\n- **MCP:** \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e FDR-\\u043f\\u043e\\u043f\\u0440\\u0430\\u0432\\u043a\\u0430 \\u0434\\u043b\\u044f 54\\u221281 per-task-\\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0439 (\\u22643 \\u043f\\u0430\\u0440\\u044b \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0439 \\u00d7 27 \\u0437\\u0430\\u0434\\u0430\\u0447); \\u043d\\u0430 \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442\\u0435 \\u2014 \\u043e\\u0434\\u043d\\u0430 \\u043f\\u043e\\u043f\\u0440\\u0430\\u0432\\u043a\\u0430 `Holm` \\u0434\\u043b\\u044f k=2 (OPRO-best vs \\u043a\\u0430\\u0436\\u0434\\u044b\\u043c baseline) \\u0432 \\u0430\\u0433\\u0440\\u0435\\u0433\\u0430\\u0442\\u0435 Wilcoxon.\\n- **Frequentist + Bayesian sanity:** \\u0434\\u043b\\u044f `task_acc_i` \\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u0441\\u0447\\u0438\\u0442\\u0430\\u0435\\u043c **\\u03b2-distribution CI** (Wilson) \\u0438 **Bayesian paired comparison** \\u043f\\u0440\\u0438 \\u0441\\u043b\\u0430\\u0431\\u043e\\u043c uniform-prior (\\u0434\\u043b\\u044f \\u043f\\u0440\\u043e\\u0437\\u0440\\u0430\\u0447\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0438 \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0438\\u044f p-hacking); \\u043e\\u0442\\u0447\\u0451\\u0442 \\u043e \\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0438 \\u043a prior (\\u0443\\u0437\\u043a\\u0438\\u0439 range).\\n- **\\u041c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c \\u043f\\u0430\\u0440 \\\"OPRO vs baseline\\\":** \\u0432\\u0441\\u0435 3 \\u043f\\u0430\\u0440\\u044b (`OPRO-best` vs `LTSBS`, `OPRO-best` vs `empty`, \\u0438, \\u0435\\u0441\\u043b\\u0438 \\u0435\\u0441\\u0442\\u044c top-k, `OPRO-top-k` vs `LTSBS`) \\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u044f\\u044e\\u0442\\u0441\\u044f \\u043d\\u0435\\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u043e; **\\u043f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u043e\\u0439** \\u0433\\u0438\\u043f\\u043e\\u0442\\u0435\\u0437\\u043e\\u0439 \\u043e\\u0431\\u044a\\u044f\\u0432\\u043b\\u044f\\u0435\\u043c `OPRO-best > empty` (\\u043d\\u0430\\u0438\\u043c\\u0435\\u043d\\u0435\\u0435 \\u0442\\u0440\\u0438\\u0432\\u0438\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f), **\\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u043e\\u0439** \\u2014 `OPRO-best > LTSBS`. \\u042d\\u0442\\u043e \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f **\\u0434\\u043e** \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430 \\u0430\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430.\\n- **Bootstrap \\u043f\\u043e \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c:** `B=10 000` \\u0440\\u0435\\u0441\\u044d\\u043c\\u043f\\u043b\\u0438\\u043d\\u0433\\u043e\\u0432 27 \\u0437\\u0430\\u0434\\u0430\\u0447 \\u0434\\u043b\\u044f CI \\u043d\\u0430 \\u0440\\u0430\\u0437\\u043d\\u0438\\u0446\\u0435 `macro(OPRO) \\u2212 macro(baseline)`.\\n- **\\u0421\\u0442\\u043e\\u043f-\\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u0430:** \\u043d\\u0435 \\u043f\\u0440\\u0438\\u043d\\u0438\\u043c\\u0430\\u0442\\u044c \\u0437\\u043d\\u0430\\u0447\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c per-task \\u043f\\u0440\\u0438 n_task<50 \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432; \\u043e\\u0442\\u043c\\u0435\\u0447\\u0430\\u0442\\u044c \\u0442\\u0430\\u043a\\u0438\\u0435 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 \\u0444\\u043b\\u0430\\u0433\\u043e\\u043c \\\"low-power\\\".\\n\\n### B.5. \\u041e\\u0442\\u0447\\u0451\\u0442 \\u0438 \\u0432\\u043e\\u0441\\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c\\n- **Outputs \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430 (\\u043d\\u0435 \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430, \\u0438\\u0431\\u043e design-only):** YAML/JSON-\\u043a\\u043e\\u043d\\u0444\\u0438\\u0433 \\u0441 (i) \\u0442\\u043e\\u0447\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0440\\u043e\\u043a\\u043e\\u0439 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438 (OPRO-best, OPRO-top-k, LTSBS, empty); (ii) \\u0441\\u043f\\u0438\\u0441\\u043a\\u043e\\u043c 27 \\u0437\\u0430\\u0434\\u0430\\u0447 BBH \\u0441 \\u0447\\u0438\\u0441\\u043b\\u043e\\u043c \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432; (iii) \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u0430\\u043c\\u0438 \\u0434\\u0435\\u043a\\u043e\\u0434\\u0438\\u043d\\u0433\\u0430; (iv) few-shot \\u0440\\u0435\\u0436\\u0438\\u043c\\u043e\\u043c; (v) OPRO-\\u043f\\u0440\\u043e\\u0432\\u0430\\u043d\\u0430\\u0441\\u043e\\u043c (\\u0441\\u0442\\u0430\\u0442\\u044c\\u044f, \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0430, \\u0441\\u0442\\u0440\\u043e\\u043a\\u0430); (vi) \\u043a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0435\\u043c \\u043f\\u0430\\u0440\\u0441\\u0438\\u043d\\u0433\\u0430; (vii) \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u0435\\u0439 \\\"\\u0433\\u0438\\u043f\\u043e\\u0442\\u0435\\u0437\\u044b \\u2194 \\u0441\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u0442\\u0435\\u0441\\u0442\\u044b \\u2194 \\u03b1-\\u043f\\u043e\\u043f\\u0440\\u0430\\u0432\\u043a\\u0430\\\".\\n- **Repro-\\u0447\\u0435\\u043a:** \\u0434\\u043b\\u044f \\u0432\\u044b\\u0431\\u0440\\u0430\\u043d\\u043d\\u043e\\u0439 LLM \\u043e\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u0435 \\u0442\\u043e\\u0447\\u043d\\u043e\\u0439 \\u043a\\u043e\\u043c\\u0430\\u043d\\u0434\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0440\\u043e\\u043a\\u0438 (\\u0438\\u043b\\u0438 signature REST-\\u0437\\u0430\\u043f\\u0440\\u043e\\u0441\\u0430) + seeds + \\u0432\\u0435\\u0440\\u0441\\u0438\\u044f \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438; \\u0441\\u043f\\u0438\\u0441\\u043e\\u043a \\u0432\\u0441\\u0435\\u0445 random-state; SHA-256 \\u0444\\u0430\\u0439\\u043b\\u043e\\u0432 BBH-\\u0441\\u043f\\u043b\\u0438\\u0442\\u0430 \\u0438 OPRO-\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0439.\\n- **Pre-registration \\u0441\\u0442\\u0438\\u043b\\u044f:** \\u0444\\u0438\\u043a\\u0441\\u0430\\u0446\\u0438\\u044f H0/H1, \\u03b1, MCP-\\u043f\\u0440\\u043e\\u0446\\u0435\\u0434\\u0443\\u0440\\u044b, \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u0430 \\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0438 \\u2014 **\\u0434\\u043e** \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430 (\\u0432 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0435).\\n- **\\u0413\\u0440\\u0430\\u0444\\u0438\\u043a\\u0438:** forest-plot per-task paired-difference \\u0441 Wilson-CI; boxplot `task_acc` \\u043f\\u043e 27 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430\\u043c \\u0434\\u043b\\u044f \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e \\u0443\\u0440\\u043e\\u0432\\u043d\\u044f \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438; bar-plot `macro`- \\u0438 `micro`-acc \\u0441 95%-CI.\\n\\n---\\n\\n## \\u042d\\u0442\\u0430\\u043f C \\u2014 \\u041a\\u043b\\u044e\\u0447\\u0435\\u0432\\u044b\\u0435 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f \\u0438 \\u043d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438\\n\\n### C.0. \\u041e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u044f \\u0441\\u0440\\u0435\\u0434\\u044b (\\u0442\\u0440\\u0435\\u0431\\u0443\\u044e\\u0442 \\u043f\\u0440\\u044f\\u043c\\u043e\\u0433\\u043e \\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043d\\u0438\\u044f \\u0432 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0435)\\n1. **bubblewrap + network=disabled + GPU=\\u043d\\u0435\\u0442** \\u2014 \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0438\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0446\\u0438\\u044f LLM \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u0430; `pip install` \\u0438\\u0437 PyPI \\u043d\\u0435 \\u043f\\u0440\\u043e\\u0445\\u043e\\u0434\\u0438\\u0442 (DNS fail). \\u041b\\u044e\\u0431\\u044b\\u0435 Python-\\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 (`numpy`, `scipy`, `statsmodels`, `datasets`, `transformers`) \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442. **\\u0422\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f:** \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u0442\\u0441\\u044f \\u043b\\u0438, \\u0447\\u0442\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442 \\u043f\\u043e\\u043b\\u043d\\u043e\\u0446\\u0435\\u043d\\u043d\\u044b\\u0439 runtime-\\u043f\\u043b\\u0430\\u043d (\\u0442\\u043e\\u0433\\u0434\\u0430 \\u043d\\u0430\\u0434\\u043e \\u0434\\u0435\\u043a\\u043b\\u0430\\u0440\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u00ab\\u0432\\u043d\\u0435 bubblewrap\\u00bb), \\u0438\\u043b\\u0438 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e paper-faithful-\\u0440\\u0435\\u043a\\u043e\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044e \\u043d\\u0430 \\u043e\\u0441\\u043d\\u043e\\u0432\\u0435 \\u043e\\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0445 \\u0447\\u0438\\u0441\\u0435\\u043b (\\u0442\\u043e\\u0433\\u0434\\u0430 environment-\\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u044f \\u043d\\u0435 \\u0431\\u043b\\u043e\\u043a\\u0438\\u0440\\u0443\\u044e\\u0442 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d).\\n2. **`actor_step_budget=60`** \\u2014 \\u043b\\u0438\\u043c\\u0438\\u0442 \\u0448\\u0430\\u0433\\u043e\\u0432 \\u043c\\u043e\\u0438\\u0445 tool-\\u0432\\u044b\\u0437\\u043e\\u0432\\u043e\\u0432; design-only \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u0434\\u043e\\u043b\\u0436\\u0435\\u043d \\u0443\\u043a\\u043b\\u0430\\u0434\\u044b\\u0432\\u0430\\u0442\\u044c\\u0441\\u044f \\u0432 \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u044b\\u0435 \\u0448\\u0430\\u0433\\u0438 (\\u043d\\u0430 \\u043c\\u043e\\u043c\\u0435\\u043d\\u0442 \\u043f\\u043e\\u0434\\u0430\\u0447\\u0438 \\u043f\\u043b\\u0430\\u043d\\u0430 \\u0443\\u0436\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043d\\u043e ~6).\\n3. **`question_budget=6`** \\u2014 \\u043b\\u0438\\u043c\\u0438\\u0442 \\u0438\\u0442\\u0435\\u0440\\u0430\\u0446\\u0438\\u0439 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u0439 \\u0441 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u0435\\u043c; \\u0441\\u043f\\u0438\\u0441\\u043e\\u043a C \\u043d\\u0438\\u0436\\u0435 \\u0440\\u0430\\u043d\\u0436\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d \\u043f\\u043e \\u043a\\u0440\\u0438\\u0442\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u0438, \\u0447\\u0442\\u043e\\u0431\\u044b \\u0443\\u043b\\u043e\\u0436\\u0438\\u0442\\u044c\\u0441\\u044f.\\n\\n### C.1. \\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f \\u0441\\u043e \\u0441\\u0442\\u0430\\u0442\\u0443\\u0441\\u043e\\u043c \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0430\\n| | \\u0414\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435 | \\u0421\\u0442\\u0430\\u0442\\u0443\\u0441 |\\n|---|---|---|\\n| A1 | \\u0418\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0438 OPRO: arXiv:2309.03409 (Yang et al., 2023); BBH: arXiv:2210.09261 (Suzgun et al., 2022); LTSBS CoT: arXiv:2205.11916 (Kojima et al., 2022) | **\\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u043e \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u043c, \\u043d\\u043e \\u0441\\u0430\\u043c\\u0438 \\u0444\\u0430\\u0439\\u043b\\u044b \\u0441\\u0442\\u0430\\u0442\\u0435\\u0439 \\u0432 `/workspace` \\u043e\\u0442\\u0441\\u0443\\u0442\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442** \\u2014 \\u043f\\u043e\\u043b\\u0430\\u0433\\u0430\\u0435\\u043c\\u0441\\u044f \\u043d\\u0430 \\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438; **\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f**, \\u043d\\u0435\\u043b\\u044c\\u0437\\u044f \\u043b\\u0438 \\u043f\\u0440\\u0438\\u043b\\u043e\\u0436\\u0438\\u0442\\u044c PDF/MD \\u0441\\u0442\\u0430\\u0442\\u0435\\u0439. |\\n| A2 | BBH \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0438\\u0442 27 \\u0437\\u0430\\u0434\\u0430\\u0447 \\u0432 canary-\\u0441\\u043f\\u043b\\u0438\\u0442\\u0435 \\u043f\\u043e 250 \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432 \\u043a\\u0430\\u0436\\u0434\\u0430\\u044f | **\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f** (\\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0434\\u0438\\u0442\\u044c \\u0442\\u043e\\u0447\\u043d\\u043e\\u0435 \\u0447\\u0438\\u0441\\u043b\\u043e \\u043f\\u0440\\u0438\\u043c\\u0435\\u0440\\u043e\\u0432 per task \\u0438 \\u0444\\u043e\\u0440\\u043c\\u0430\\u0442 \\u0444\\u0430\\u0439\\u043b\\u0430). |\\n| A3 | \\u041c\\u043e\\u0434\\u0435\\u043b\\u044c \\u043f\\u043e \\u0443\\u043c\\u043e\\u043b\\u0447\\u0430\\u043d\\u0438\\u044e \\u0432 \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u043c OPRO \\u0434\\u043b\\u044f BBH \\u2014 `text-bison` / PaLM 2 | **\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f**: \\u043a\\u0430\\u043a\\u0430\\u044f \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e LLM \\u0434\\u043e\\u043b\\u0436\\u043d\\u0430 \\u0431\\u044b\\u0442\\u044c \\u0446\\u0435\\u043b\\u044c\\u044e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0430? \\u2014 \\u044d\\u0442\\u043e \\u0441\\u0438\\u043b\\u044c\\u043d\\u043e \\u0432\\u043b\\u0438\\u044f\\u0435\\u0442 \\u043d\\u0430 \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c\\u044b\\u0435 \\u0446\\u0438\\u0444\\u0440\\u044b \\u0438 \\u043d\\u0430 \\u0434\\u0435\\u043a\\u043e\\u0434\\u0435\\u0440. |\\n| A4 | OPRO-best \\u2014 \\u0435\\u0434\\u0438\\u043d\\u0430\\u044f \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f, \\u043d\\u0430\\u0439\\u0434\\u0435\\u043d\\u043d\\u0430\\u044f OPRO \\u0438 \\u043e\\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u043e\\u0432\\u0430\\u043d\\u043d\\u0430\\u044f \\u0432 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435 (\\u043d\\u0435 per-task best) | **\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f**: OPRO-best = \\u043e\\u0434\\u043d\\u0430 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f \\u0438\\u0437 Appendix / \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446\\u044b \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438, \\u043b\\u0438\\u0431\\u043e \\u0432\\u044b\\u0431\\u0438\\u0440\\u0430\\u0435\\u0442\\u0441\\u044f per task? |\\n| A5 | \\u041a\\u0440\\u0438\\u0442\\u0435\\u0440\\u0438\\u0439 OPRO \\u043f\\u0440\\u0438 \\u043e\\u043f\\u0442\\u0438\\u043c\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 \\u2014 `maximize task accuracy` (accuracy-based score) \\u043d\\u0430 train-\\u0441\\u043f\\u043b\\u0438\\u0442\\u0435 BBH | **\\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u043e \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u043c** \\u0434\\u043b\\u044f \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 (\\u043d\\u043e \\u0438\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c train-\\u0441\\u043f\\u043b\\u0438\\u0442\\u0430 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f \\u2014 leakage \\u0441\\u043c. \\u043d\\u0438\\u0436\\u0435). |\\n| A6 | Few-shot \\u0440\\u0435\\u0436\\u0438\\u043c \\u043f\\u043e \\u0443\\u043c\\u043e\\u043b\\u0447\\u0430\\u043d\\u0438\\u044e \\u2014 **0-shot + instruction-only**, \\u043a\\u0430\\u043a \\u0432 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u043c \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0435 OPRO \\u043d\\u0430 BBH | **\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f**: OPRO \\u043d\\u0430 BBH \\u0432 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043b **0-shot** (\\u043d\\u0435\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e other ablation \\u2014 3-shot LTSBS). \\u041d\\u0443\\u0436\\u043d\\u043e \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0434\\u0438\\u0442\\u044c \\u043f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u044b\\u0439 \\u0440\\u0435\\u0436\\u0438\\u043c. |\\n| A7 | \\u0414\\u0435\\u043a\\u043e\\u0434\\u0438\\u043d\\u0433 \\u0432 OPRO/BBH: temperature=0 (greedy) | **\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f**; \\u0432 \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u044b\\u0445 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430\\u0445 \\u0447\\u0430\\u0441\\u0442\\u0438\\u0447\\u043d\\u043e \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043b\\u043e\\u0441\\u044c temperature>0 \\u0434\\u043b\\u044f \\u0434\\u0438\\u0441\\u043f\\u0435\\u0440\\u0441\\u0438\\u0438. |\\n| A8 | \\u041f\\u0430\\u0440\\u0441\\u0438\\u043d\\u0433 \\u043e\\u0442\\u0432\\u0435\\u0442\\u0430: \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u044b\\u0439 exact-match \\u043f\\u043e \\u043f\\u0440\\u0435\\u0434\\u0441\\u043a\\u0430\\u0437\\u0430\\u043d\\u043d\\u043e\\u043c\\u0443 \\u0444\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u043c\\u0443 \\u0442\\u043e\\u043a\\u0435\\u043d\\u0443 / \\u0441\\u0442\\u0440\\u043e\\u043a\\u0435 \\u0438\\u0437 `final answer` | **\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f**: \\u043d\\u0443\\u0436\\u0435\\u043d BBH-\\u043e\\u0444\\u0438\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0441\\u043a\\u0440\\u0438\\u043f\\u0442 \\u043e\\u0446\\u0435\\u043d\\u043a\\u0438. |\\n| A9 | Baseline-1 = \\u0434\\u043e\\u0441\\u043b\\u043e\\u0432\\u043d\\u043e \\u0441\\u0442\\u0440\\u043e\\u043a\\u0430 `\\\"Let's think step by step.\\\"` (\\u0441 \\u0442\\u043e\\u0447\\u043a\\u043e\\u0439 \\u0438 \\u043f\\u0440\\u043e\\u0431\\u0435\\u043b\\u0430\\u043c\\u0438), Baseline-2 = \\u043f\\u0443\\u0441\\u0442\\u0430\\u044f \\u0441\\u0442\\u0440\\u043e\\u043a\\u0430 | **\\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u043e \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u043c** \\u2014 \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442 BBH/OPRO \\u0444\\u043e\\u0440\\u043c\\u0443\\u043b\\u0438\\u0440\\u043e\\u0432\\u043a\\u0438. |\\n| A10 | \\u041f\\u043e\\u043b\\u043d\\u044b\\u0439 eval-\\u0441\\u043f\\u043b\\u0438\\u0442 BBH, \\u0431\\u0435\\u0437 \\u0441\\u0443\\u0431-\\u0441\\u044d\\u043c\\u043f\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f | **\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044f** \\u0432 \\u0441\\u0432\\u0435\\u0442\\u0435 runtime-\\u0431\\u044e\\u0434\\u0436\\u0435\\u0442\\u0430. |\\n| A11 | BBH \\u043d\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u043e\\u0432\\u0430\\u043b\\u0441\\u044f \\u043a\\u0430\\u043a train-\\u0434\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0446\\u0435\\u043b\\u0435\\u0432\\u043e\\u0439 LLM (\\u043d\\u0435\\u0442 leakage) | **\\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u043e \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u043e\\u043c** \\u0434\\u043b\\u044f text-bison/PaLM 2 (per \\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438 OPRO); \\u043d\\u043e **\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u0435\\u043c** \\u0434\\u043b\\u044f \\u043b\\u044e\\u0431\\u043e\\u0439 \\u0434\\u0440\\u0443\\u0433\\u043e\\u0439 LLM. |\\n| A12 | \\u0410\\u043d\\u0430\\u043b\\u0438\\u0437 paired, per-task Wilcoxon + McNemar + FDR(q=0.05) + bootstrap(10k) | **\\u043f\\u0440\\u0435\\u0434\\u043b\\u043e\\u0436\\u0435\\u043d\\u043e \\u043c\\u043d\\u043e\\u0439**; **\\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u0435\\u043c**. |\\n\\n### C.2. \\u0420\\u0430\\u043d\\u0436\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0441\\u043f\\u0438\\u0441\\u043e\\u043a \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u0439 (\\u0435\\u0441\\u043b\\u0438 \\u0432\\u044b \\u0437\\u0430\\u0439\\u0434\\u0451\\u0442\\u0435 \\u0432 approach_review)\\n1. **\\u041a\\u0430\\u043a\\u0430\\u044f LLM \\u0434\\u043e\\u043b\\u0436\\u043d\\u0430 \\u0431\\u044b\\u0442\\u044c \\u0446\\u0435\\u043b\\u044c\\u044e \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430?** (\\u043f\\u043e \\u0443\\u043c\\u043e\\u043b\\u0447\\u0430\\u043d\\u0438\\u044e \\u2014 `text-bison`/PaLM 2, \\u043a\\u0430\\u043a \\u0432 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435 OPRO \\u043d\\u0430 BBH; \\u0430\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u0430 \\u2014 GPT-3.5-turbo / GPT-4 / \\u043b\\u043e\\u043a\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c).\\n2. **\\u0418\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a OPRO-\\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0439:** \\u0431\\u0435\\u0440\\u0451\\u043c \\u043b\\u0438 \\u0431\\u0443\\u043a\\u0432\\u0430\\u043b\\u044c\\u043d\\u043e \\u043e\\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u0438 \\u0438\\u0437 \\u0442\\u0430\\u0431\\u043b\\u0438\\u0446 OPRO (Appendix), \\u0438\\u043b\\u0438 \\u0435\\u0441\\u0442\\u044c **OPRO-\\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u044b \\u0432 \\u0440\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u0438** (\\u043d\\u0435 \\u043d\\u0430\\u0439\\u0434\\u0435\\u043d\\u044b \\u2014 \\u043a\\u0443\\u0434\\u0430 \\u043f\\u0440\\u0438\\u043b\\u043e\\u0436\\u0438\\u0442\\u044c?)\\n3. **\\u0420\\u0435\\u0436\\u0438\\u043c few-shot:** 0-shot (instruction-only, \\u043a\\u0430\\u043a \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u0439 \\u0440\\u0435\\u0436\\u0438\\u043c OPRO) \\u0438\\u043b\\u0438 3-shot?\\n4. **OPRO-best:** \\u043e\\u0434\\u043d\\u0430 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0438\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f best \\u043d\\u0430 \\u0432\\u0441\\u0435 27 \\u0437\\u0430\\u0434\\u0430\\u0447, \\u0438\\u043b\\u0438 per-task best?\\n5. **\\u0414\\u0435\\u043a\\u043e\\u0434\\u0438\\u043d\\u0433:** \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c `temperature=0.0` greedy, \\u0438\\u043b\\u0438 \\u0434\\u0430\\u0442\\u044c 3-seed-\\u0443\\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u043d\\u0438\\u0435 \\u043f\\u0440\\u0438 temperature>0?\\n6. **Runtime-\\u0441\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0439:** design-only \\u0432 bubblewrap (paper-faithful \\u0440\\u0435\\u043a\\u043e\\u043d\\u0441\\u0442\\u0440\\u0443\\u043a\\u0446\\u0438\\u044f) **\\u0438\\u043b\\u0438** \\u043f\\u043e\\u043b\\u043d\\u043e\\u0446\\u0435\\u043d\\u043d\\u044b\\u0439 runtime-\\u043f\\u043b\\u0430\\u043d \\u0441 \\u0432\\u044b\\u043d