ons\": [\"\\u0421\\u0440\\u0435\\u0434\\u0430 bubblewrap \\u0434\\u0435\\u0439\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u0438\\u0437\\u043e\\u043b\\u0438\\u0440\\u0443\\u0435\\u0442 \\u0441\\u0435\\u0442\\u044c (DNS-failure \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0451\\u043d curl). \\u041b\\u044e\\u0431\\u044b\\u0435 \\u0432\\u043d\\u0435\\u0448\\u043d\\u0438\\u0435 \\u043f\\u0430\\u043a\\u0435\\u0442\\u044b \\u043d\\u0435\\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u044b; \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u043d\\u0435 \\u043c\\u043e\\u0436\\u0435\\u0442 \\u043e\\u043f\\u0438\\u0440\\u0430\\u0442\\u044c\\u0441\\u044f \\u043d\\u0430 Python-\\u0441\\u0442\\u0435\\u043a \\u0441\\u0432\\u0435\\u0440\\u0445 \\u043f\\u0440\\u0435\\u0434\\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e. \\u041e\\u0434\\u043d\\u0430\\u043a\\u043e \\u0441\\u0430\\u043c\\u0430 \\u0437\\u0430\\u0434\\u0430\\u0447\\u0430 \\u043f\\u043e\\u043c\\u0435\\u0447\\u0435\\u043d\\u0430 design-only, \\u043f\\u043e\\u044d\\u0442\\u043e\\u043c\\u0443 \\u044d\\u0442\\u043e \\u043d\\u0435 \\u0431\\u043b\\u043e\\u043a\\u0438\\u0440\\u0443\\u0435\\u0442 \\u0444\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d, \\u043b\\u0438\\u0448\\u044c \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442 \\u044f\\u0432\\u043d\\u043e \\u043e\\u043f\\u0438\\u0441\\u0430\\u0442\\u044c runtime-\\u0441\\u0446\\u0435\\u043d\\u0430\\u0440\\u0438\\u0439.\", \"\\u041f\\u043e\\u0434\\u0440\\u0430\\u0437\\u0443\\u043c\\u0435\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f OPRO-\\u043f\\u0430\\u0439\\u043f\\u043b\\u0430\\u0439\\u043d \\u0438 BBH-\\u043e\\u0446\\u0435\\u043d\\u043a\\u0430 \\u00ab\\u043a\\u0430\\u043a \\u0432 \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u043f\\u0443\\u0431\\u043b\\u0438\\u043a\\u0430\\u0446\\u0438\\u04