sk)/len(rows_per_task)\n    base_e = sum(t[\"empty\"] for t in rows_per_task)/len(rows_per_task)\n    dL, dE = [], []\n    for _ in range(n_boot):\n        idxs = [rng.randrange(len(rows_per_task)) for _ in rows_per_task]\n        mOPRO = sum(rows_per_task[i][\"OPRO_best\"] for i in idxs)/len(idxs)\n        mL    = sum(rows_per_task[i][\"LTSBS\"]      for i in idxs)/len(idxs)\n        mE    = sum(rows_per_task[i][\"empty\"]      for i in idxs)/len(idxs)\n        dL.append(mOPRO-mL); dE.append(mOPRO-mE)\n    dL.sort(); dE.sort()\n    def ci(v): return (v[int(0.025*len(v))], v[int(0.975*len(v))])\n    return {\"point\": {\"Δ_LTSBS\":base-base_l,\"Δ_empty\":base-base_e},\n            \"ci95\":  {\"Δ_LTSBS\":ci(dL),\"Δ_empty\":ci(dE)}}\n```\n\n> Note: the scipy/normal-approx path above uses only `math.erf` (Py3 stdlib). On small `n` use exact Wilcoxon from `statistics` (Python 3.12 does not ship it; documented in §h as open-engineering — execute outside bubblewrap with `scipy.stats.wilcoxon`).\n\n### f.4 — Cross-family extension stub\n\n```python\nSECONDARY_MODELS = [\"gpt-3.5-turbo-0613\", \"gpt-4-0613\"]\n# Each such model runs the same Config / inference / pairing code, with the\n# audit pointer set in §d asserting: instruction-string unchanged; prompt-template\n# unchanged; decoding unchanged (or temperature_mapped_to_chat_api=0 equivalent).\n# No API call is performed in the bubblewrap plan; this is a documented option.\n```\n\nDESIGN_EOF\necho \"wrote_part_6\"; wc -l /workspace/experiment_design.md", "timeout_seconds": 60, "kind": "ExecuteCheckAction"}, "tool_name": "execute_check", "tool_call_id": "call-755c669d-19a8-4444-b4c2-97d309e5523e", "tool_call": {"id": "call-755c669d-19a8-4444-b4c2-97d309e5523e", "responses_item_id": null, "name": "execute_check", "arguments": "{\"summary\": \"Stage 6 \\u2014 implementation spec\", \"command\": \"cat >> /workspace/experiment_design.md << 'DESIGN_EOF'\\n---\\n\\n## (f) Implementation spec \\u2014 pseudocode (deferred-to-e