   mid = (r + (r + (j-i))) / 2.0\\n        for k in range(i,j+1): ranks[k] = mid\\n        r = j+2\\n    Wplus  = sum(ranks[i] for i,(a,s) in enumerate(nonzero) if s>0)\\n    Wminus = sum(ranks[i] for i,(a,s) in enumerate(nonzero) if s<0)\\n    mu = n*(n+1)/4\\n    sigma = math.sqrt(n*(n+1)*(2*n+1)/24)\\n    z = (Wplus - mu - 0.5)/sigma if alternative==\\\"greater\\\" else (Wplus - mu)/sigma\\n    p = 0.5*(1 - math.erf(z/math.sqrt(2)))\\n    return {\\\"W+\\\":Wplus,\\\"W-\\\":Wminus,\\\"p\\\":p,\\\"n_nonzero\\\":n,\\\"z\\\":z}\\n\\n# --- generate 27 paired CSVs, each of n_t=200 simulated paired examples ---\\ntmpdir = tempfile.mkdtemp(prefix=\\\"opro_smoke_\\\")\\nseed = 0\\nrng = random.Random(seed)\\nrows_per_task = []\\nPER_TASK_N = 200  # illustrative, \\u2264250 as per \\u00a7c.5\\nfor t in range(27):\\n    # ground-truth instruction-strength signal: OPRO-best has +0.05 accuracy over LTSBS, +0.10 over empty (synthetic)\\n    base_p = rng.uniform(0.3, 0.85)\\n    p_opro = min(1.0, base_p + 0.05)\\n    p_ltsbs = max(0.0, base_p)\\n    p_empty = max(0.0, base_p - 0.05)\\n    rows = []\\n    for i in range(PER_TASK_N):\\n        rows.append({\\\"id\\\": f\\\"t{t:02d}_e{i:03d}\\\",\\n                     \\\"OPRO_best\\\": 1 if rng.random() < p_opro  else 0,\\n                     \\\"LTSBS\\\":      1 if rng.random() < p_ltsbs else 0,\\n                     \\\"empty\\\":      1 if rng.random() < p_empty else 0})\\n    fp = os.path.join(tmpdir, f\\\"task_{t:02d}__paired.csv\\\")\\n    with open(fp, \\\"w\\\") as f:\\n        w = csv.DictWriter(f, fieldnames=[\\\"id\\\",\\\"OPRO_best\\\",\\\"LTSBS\\\",\\\"empty\\\"])\\n        w.writeheader(); w.writerows(rows)\\n    accs = {I: sum(r[I] for r in rows)/len(rows) for I in INSTRUCTIONS}\\n    rows_per_task.append({\\\"task\\\": t, **accs, \\\"n\\\": PER_TASK_N})\\n\\n# --- collect aggregate accs ---\\ndef macro(v): return sum(row[v] for row in rows_per_task)/len(rows_per_task)\\ndef micro(v):\\n    total = sum(row[v]*row[\\\"n\\\"] for row in rows_per_task)\\n    n     = sum(row[\\\"n\\\"] for row in rows_per_task)\\n    return total/n\\n\\nprint(\\\"== Per-task macro-acc (synthetic) ==\\\")\\nfor I in INSTRUCTIONS:\\n    print(f\\\"  macro({I})={macro(I):.4f}   micro({I})={micro(I):.4f}   Wilson95(macro)={wilson_ci(macro(I),27)}\\\")\\n\\n# --- per-task McNemar (synthetic) ---\\npvals_l=[]; pvals_e=[]\\nfor t in range(27):\\n    p_opro = rows_per_task[t][\\\"OPRO_best\\\"]; n=rows_per_task[t][\\\"n\\\"]\\n    rows = list(csv.DictReader(open(os.path.join(tmpdir,f\\\"task_{t:02d}__paired.csv\\\"))))\\n    b10_l = sum(1 for r in rows if r[\\\"OPRO_best\\\"]==\\\"1\\\" and r[\\\"LTSBS\\\"]==\\\"0\\\")\\n    b01_l = sum(1 for r in rows if r[\\\"OPRO_best\\\"]==\\\"0\\\" and r[\\\"LTSBS\\\"]==\\\"1\\\")\\n    b10_e = sum(1 for r in rows if r[\\\"OPRO_best\\\"]==\\\"1\\\" and r[\\\"empty\\\"]==\\\"0\\\")\\n    b01_e = sum(1 for r in rows if r[\\\"OPRO_best\\\"]==\\\"0\\\" and r[\\\"empty\\\"]==\\\"1\\\")\\n    chi_l = mcnemar(b10_l, b01_l); chi_e = mcnemar(b10_e, b01_e)\\n    p_l = 1 - math.erf(math.sqrt(chi_l)/math.sqrt(2)) if chi_l>0 else 1.0\\n    p_e = 1 - math.erf(math.sqrt(chi_e)/math.sqrt(2)) if chi_e>0 else 1.0\\n    p_l = max(min(p_l,1.0),0.0);  p_e = max(min(p_e,1.0),0.0)\\n    pvals_l.append(p_l); pvals_e.append(p_e)\\nfdr_l = bh_fdr(pvals_l); fdr_e = bh_fdr(pvals_e)\\nprint(f\\\"== McNemar per-task (synthetic; n_per_task={PER_TASK_N}) ==\\\")\\nprint(f\\\"  #significant at FDR-BH q<0.05: vs LTSBS={sum(1 for p in fdr_l if p<0.05)}  vs empty={sum(1 for p in fdr_e if p<0.05)}\\\")\\n\\n# --- aggregate Wilcoxon (synthetic) ---\\ndL = [rows_per_task[t][\\\"OPRO_best\\\"] - rows_per_task[t][\\\"LTSBS\\\"] for t in range(27)]\\ndE = [rows_per_task[t][\\\"OPRO_best\\\"] - rows_per_task[t][\\\"empty\\\"] for t in range(27)]\\nresL = paired_wilcoxon(dL); resE = paired_wilcoxon(dE)\\nadj = holm([resL[\\\"p\\\"], resE[\\\"p\\\"]])\\nprint(f\\\"== Aggregate paired Wilcoxon (synthetic) ==\\\")\\nprint(f\\\"  vs LTSBS: W+={resL['W+']:.1f} z={resL['z']:.3f} p={resL['p']:.4f}  Holm-adj={adj[0]:.4f}\\\")\\nprint(f\\\"  vs empty: W+={resE['W+']:.1f} z={resE['z']:.3f} p={resE['p']:.4f}  Holm-adj={adj[1]:.4f}\\\")\\n\\n# --- audit: SHA-256 of literal instructions (matches \\u00a7d contract) ---\\nfor label,text in [(\\\"OPRO_best\\\",\\\"Take a deep breath and work on this problem step-by-step.\\\"),\\n                   (\\\"LTSBS\\\",\\\"Let's think step by step.\\\"),\\n                   (\\\"empty\\\",\\\"\\\")]:\\n    fp = os.path.join(tmpdir,label+\\\".txt\\\")\\n    open(fp,\\\"w\\\").write(text.strip())\\n    h = hashlib.sha256(open(fp,\\\"rb\\\").read()).hexdigest()\\n    print(f\\\"  audit[{label}] = {h}  bytes={len(text.strip())}\\\")\\n\\n# cleanup\\nimport shutil; shutil.rmtree(tmpdir,ignore_errors=True)\\nprint(\\\"SMOKE_OK\\\")\\nPYEOF\", \"exit_code\": 0, \"timed_out\": false, \"elapsed_seconds\": 0.064, \"output\": \"== Per-task macro-acc (synthetic) ==\\n  macro(OPRO_best)=0.6094   micro(OPRO_best)=0.6094   Wilson95(macro)=(0.42308803502921677, 0.7685362646180127)\\n  macro(LTSBS)=0.5628   micro(LTSBS)=0.5628   Wilson95(macro)=(0.37971551749457266, 0.7302009589528232)\\n  macro(empty)=0.5048   micro(empty)=0.5048   Wilson95(macro)=(0.3277576369177865, 0.6806725353171171)\\n== McNemar per-task (synthetic; n_per_task=200) ==\\n  #significant at FDR-BH q<0.05: vs LTSBS=0  vs empty=14\\n== Aggregate paired Wilcoxon (synthetic) ==\\n  vs LTSBS: W+=366.0 z=4.240 p=0.0000  Holm-adj=0.0000\\n  vs empty: W+=394.5 z=4.925 p=0.0000  Holm-adj=0.0000\\n  audit[OPRO_best] = 9dd5a74eb84a82dc71b5bbd4bc3d55e219373f2acf03a7368e8acb8f921646b7  bytes=57\\n  audit[LTSBS] = c93f8475e1d8436774c22375c04c67bee94091b90c8f00a031f953857d595661  bytes=25\\n  audit[empty] = e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855  bytes=0\\nSMOKE_OK\\n\", \"output_truncated\": false}"}], "is_error": false, "kind": "BenchmarkObservation"}, "action_id": "3dfc